-- 零星材料增加分类字段
ALTER TABLE miscellaneous_materials ADD COLUMN IF NOT EXISTS category varchar(50);

-- 存量数据按材料名启发式归类（匹配不到默认"其他材料"）
UPDATE miscellaneous_materials SET category = '五金电料' WHERE category IS NULL AND (material_name ILIKE '%铁丝%' OR material_name ILIKE '%扎丝%' OR material_name ILIKE '%铁钉%' OR material_name ILIKE '%螺丝%' OR material_name ILIKE '%螺栓%' OR material_name ILIKE '%螺母%' OR material_name ILIKE '%垫片%' OR material_name ILIKE '%合页%' OR material_name ILIKE '%门锁%' OR material_name ILIKE '%胶带%' OR material_name ILIKE '%膨胀%' OR material_name ILIKE '%铆钉%' OR material_name ILIKE '%钢丝%' OR material_name ILIKE '%钢钉%' OR material_name ILIKE '%卡扣%' OR material_name ILIKE '%挂钩%');
UPDATE miscellaneous_materials SET category = '电线电气' WHERE category IS NULL AND (material_name ILIKE '%电线%' OR material_name ILIKE '%电缆%' OR material_name ILIKE '%穿线管%' OR material_name ILIKE '%线盒%' OR material_name ILIKE '%开关%' OR material_name ILIKE '%插座%' OR material_name ILIKE '%灯泡%' OR material_name ILIKE '%灯头%' OR material_name ILIKE '%配电%' OR material_name ILIKE '%漏保%' OR material_name ILIKE '%空开%' OR material_name ILIKE '%线管%' OR material_name ILIKE '%绝缘%' OR material_name ILIKE '%电胶布%' OR material_name ILIKE '%灯管%' OR material_name ILIKE '%led%');
UPDATE miscellaneous_materials SET category = '水暖管件' WHERE category IS NULL AND (material_name ILIKE '%pvc%' OR material_name ILIKE '%ppr%' OR material_name ILIKE '%水管%' OR material_name ILIKE '%管件%' OR material_name ILIKE '%弯头%' OR material_name ILIKE '%三通%' OR material_name ILIKE '%阀门%' OR material_name ILIKE '%水龙头%' OR material_name ILIKE '%生料带%' OR material_name ILIKE '%接头%' OR material_name ILIKE '%法兰%' OR material_name ILIKE '%软管%' OR material_name ILIKE '%地漏%' OR material_name ILIKE '%堵头%' OR material_name ILIKE '%管卡%' OR material_name ILIKE '%下水%');
UPDATE miscellaneous_materials SET category = '焊接耗材' WHERE category IS NULL AND (material_name ILIKE '%焊条%' OR material_name ILIKE '%焊丝%' OR material_name ILIKE '%切割片%' OR material_name ILIKE '%磨光片%' OR material_name ILIKE '%氧气%' OR material_name ILIKE '%乙炔%' OR material_name ILIKE '%氩气%' OR material_name ILIKE '%导电嘴%' OR material_name ILIKE '%焊枪%' OR material_name ILIKE '%割枪%' OR material_name ILIKE '%碳棒%');
UPDATE miscellaneous_materials SET category = '工具器具' WHERE category IS NULL AND (material_name ILIKE '%工具%' OR material_name ILIKE '%电钻%' OR material_name ILIKE '%电锤%' OR material_name ILIKE '%角磨机%' OR material_name ILIKE '%扳手%' OR material_name ILIKE '%锤子%' OR material_name ILIKE '%钳子%' OR material_name ILIKE '%螺丝刀%' OR material_name ILIKE '%铁锹%' OR material_name ILIKE '%洋镐%' OR material_name ILIKE '%灰桶%' OR material_name ILIKE '%水桶%' OR material_name ILIKE '%卷尺%' OR material_name ILIKE '%靠尺%' OR material_name ILIKE '%水平尺%' OR material_name ILIKE '%钻头%' OR material_name ILIKE '%锯片%' OR material_name ILIKE '%刀片%' OR material_name ILIKE '%振动棒%' OR material_name ILIKE '%抹子%' OR material_name ILIKE '%灰刀%' OR material_name ILIKE '%扫帚%' OR material_name ILIKE '%推车%' OR material_name ILIKE '%斗车%');
UPDATE miscellaneous_materials SET category = '劳保防护' WHERE category IS NULL AND (material_name ILIKE '%安全帽%' OR material_name ILIKE '%安全带%' OR material_name ILIKE '%手套%' OR material_name ILIKE '%工服%' OR material_name ILIKE '%工作服%' OR material_name ILIKE '%绝缘鞋%' OR material_name ILIKE '%胶鞋%' OR material_name ILIKE '%雨鞋%' OR material_name ILIKE '%护目镜%' OR material_name ILIKE '%口罩%' OR material_name ILIKE '%雨衣%' OR material_name ILIKE '%雨靴%' OR material_name ILIKE '%反光%' OR material_name ILIKE '%防护服%' OR material_name ILIKE '%耳塞%' OR material_name ILIKE '%劳保%' OR material_name ILIKE '%防滑鞋%');
