UPDATE miscellaneous_materials SET category = '油料化工' WHERE category IS NULL AND (material_name ILIKE '%机油%' OR material_name ILIKE '%润滑油%' OR material_name ILIKE '%黄油%' OR material_name ILIKE '%脱模剂%' OR material_name ILIKE '%油漆%' OR material_name ILIKE '%稀料%' OR material_name ILIKE '%密封胶%' OR material_name ILIKE '%发泡胶%' OR material_name ILIKE '%玻璃胶%' OR material_name ILIKE '%柴油%' OR material_name ILIKE '%汽油%' OR material_name ILIKE '%液压油%' OR material_name ILIKE '%齿轮油%' OR material_name ILIKE '%涂料%' OR material_name ILIKE '%防腐%' OR material_name ILIKE '%胶水%' OR material_name ILIKE '%粘合剂%');
UPDATE miscellaneous_materials SET category = '其他材料' WHERE category IS NULL;

CREATE INDEX IF NOT EXISTS miscellaneous_materials_category_idx ON miscellaneous_materials (category);

